CREATE TYPE "TrackingType" AS ENUM ('BULK', 'SERIALIZED');
CREATE TYPE "TransferStatus" AS ENUM ('DRAFT', 'SUBMITTED', 'APPROVED', 'REJECTED', 'DISPATCHED', 'RECEIVED', 'DISCREPANCY', 'CANCELLED');
CREATE TYPE "TransferEventType" AS ENUM ('CREATED', 'SUBMITTED', 'APPROVED', 'REJECTED', 'DISPATCHED', 'RECEIVED', 'DISCREPANCY_RECORDED', 'COMPLETED', 'CANCELLED');
CREATE TYPE "InventoryMovementType" AS ENUM ('TRANSFER_OUT', 'TRANSFER_IN');

CREATE TABLE "catalog_items" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" UUID NOT NULL REFERENCES "organizations"("id"), "sku" TEXT NOT NULL, "name" TEXT NOT NULL, "tracking_type" "TrackingType" NOT NULL, "active" BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE ("organization_id", "sku"));
CREATE TABLE "inventory_balances" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" UUID NOT NULL REFERENCES "organizations"("id"), "location_id" UUID NOT NULL REFERENCES "locations"("id"), "catalog_item_id" UUID NOT NULL REFERENCES "catalog_items"("id"), "on_hand" INTEGER NOT NULL DEFAULT 0 CHECK ("on_hand" >= 0), "allocated" INTEGER NOT NULL DEFAULT 0 CHECK ("allocated" >= 0 AND "allocated" <= "on_hand"), "version" INTEGER NOT NULL DEFAULT 1, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("organization_id", "location_id", "catalog_item_id"));
CREATE TABLE "transfer_requests" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" UUID NOT NULL REFERENCES "organizations"("id"), "source_location_id" UUID NOT NULL REFERENCES "locations"("id"), "destination_location_id" UUID NOT NULL REFERENCES "locations"("id"), "requester_id" UUID NOT NULL REFERENCES "users"("id"), "status" "TransferStatus" NOT NULL DEFAULT 'DRAFT', "version" INTEGER NOT NULL DEFAULT 1, "idempotency_key" TEXT NOT NULL UNIQUE, "request_hash" TEXT NOT NULL, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK ("source_location_id" <> "destination_location_id"));
CREATE TABLE "transfer_lines" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "transfer_id" UUID NOT NULL REFERENCES "transfer_requests"("id"), "catalog_item_id" UUID NOT NULL REFERENCES "catalog_items"("id"), "requested_quantity" INTEGER NOT NULL CHECK ("requested_quantity" > 0), "dispatched_quantity" INTEGER NOT NULL DEFAULT 0 CHECK ("dispatched_quantity" >= 0), "received_quantity" INTEGER NOT NULL DEFAULT 0 CHECK ("received_quantity" >= 0), UNIQUE ("transfer_id", "catalog_item_id"));
CREATE TABLE "transfer_events" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "transfer_id" UUID NOT NULL REFERENCES "transfer_requests"("id"), "type" "TransferEventType" NOT NULL, "from_status" "TransferStatus", "to_status" "TransferStatus" NOT NULL, "actor_id" UUID NOT NULL REFERENCES "users"("id"), "idempotency_key" TEXT UNIQUE, "request_hash" TEXT, "reason" TEXT, "payload" JSONB, "occurred_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "inventory_ledger_entries" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" UUID NOT NULL REFERENCES "organizations"("id"), "transfer_id" UUID NOT NULL REFERENCES "transfer_requests"("id"), "transfer_line_id" UUID NOT NULL REFERENCES "transfer_lines"("id"), "catalog_item_id" UUID NOT NULL REFERENCES "catalog_items"("id"), "location_id" UUID NOT NULL REFERENCES "locations"("id"), "movement_type" "InventoryMovementType" NOT NULL, "on_hand_delta" INTEGER NOT NULL, "actor_id" UUID NOT NULL REFERENCES "users"("id"), "effective_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "posted_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "transfer_requests_organization_id_source_location_id_status_idx" ON "transfer_requests"("organization_id", "source_location_id", "status");
CREATE INDEX "transfer_events_transfer_id_occurred_at_idx" ON "transfer_events"("transfer_id", "occurred_at");
CREATE INDEX "inventory_ledger_entries_organization_location_item_effective_idx" ON "inventory_ledger_entries"("organization_id", "location_id", "catalog_item_id", "effective_at");

CREATE FUNCTION prevent_transfer_history_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'transfer events and inventory ledger entries are append-only'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER transfer_events_append_only BEFORE UPDATE OR DELETE ON "transfer_events" FOR EACH ROW EXECUTE FUNCTION prevent_transfer_history_mutation();
CREATE TRIGGER inventory_ledger_entries_append_only BEFORE UPDATE OR DELETE ON "inventory_ledger_entries" FOR EACH ROW EXECUTE FUNCTION prevent_transfer_history_mutation();
